using System.ComponentModel;
using System.Net;
using System.Text.Json;

namespace ResearchAgent;

/// <summary>
/// Simulates web search results for the research agent.
/// Replace the implementation with a real search API (Bing, Google, etc.) for production use.
/// </summary>
public static class WebSearchTool
{
    private static readonly HttpClient HttpClient = new()
    {
        Timeout = TimeSpan.FromSeconds(30),
    };

    [Description("Searches the web for information on a given query. Returns a list of relevant search results with titles, snippets, and URLs.")]
    public static async Task<string> SearchWebAsync(
        [Description("The search query to look up on the web")] string query)
    {
        // Try using a real search API if configured
        var apiKey = Environment.GetEnvironmentVariable("BING_SEARCH_API_KEY");
        if (!string.IsNullOrEmpty(apiKey))
        {
            return await SearchWithBingAsync(query, apiKey);
        }

        // Fallback: simulated search results for demonstration
        return GetSimulatedResults(query);
    }

    private static async Task<string> SearchWithBingAsync(string query, string apiKey)
    {
        var encodedQuery = WebUtility.UrlEncode(query);
        var url = $"https://api.bing.microsoft.com/v7.0/search?q={encodedQuery}&count=5";

        using var request = new HttpRequestMessage(HttpMethod.Get, url);
        request.Headers.Add("Ocp-Apim-Subscription-Key", apiKey);

        var response = await HttpClient.SendAsync(request);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync();
        using var doc = JsonDocument.Parse(json);

        var results = new List<object>();
        if (doc.RootElement.TryGetProperty("webPages", out var webPages) &&
            webPages.TryGetProperty("value", out var values))
        {
            foreach (var item in values.EnumerateArray().Take(5))
            {
                results.Add(new
                {
                    title = item.GetProperty("name").GetString(),
                    snippet = item.GetProperty("snippet").GetString(),
                    url = item.GetProperty("url").GetString(),
                });
            }
        }

        return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
    }

    private static string GetSimulatedResults(string query)
    {
        var results = new[]
        {
            new
            {
                title = $"Latest Research on {query} - Science Daily",
                snippet = $"Recent breakthroughs in {query} have shown promising results. Researchers have made significant progress in understanding the fundamental principles and practical applications.",
                url = $"https://example.com/research/{Uri.EscapeDataString(query)}/1",
            },
            new
            {
                title = $"{query}: A Comprehensive Overview - Nature",
                snippet = $"This comprehensive review covers the current state of {query}, including recent developments, key challenges, and future directions identified by leading experts in the field.",
                url = $"https://example.com/overview/{Uri.EscapeDataString(query)}/2",
            },
            new
            {
                title = $"Practical Applications of {query} - IEEE",
                snippet = $"Engineers and scientists are finding new practical applications for {query} in industry. From healthcare to telecommunications, the impact is being felt across multiple sectors.",
                url = $"https://example.com/applications/{Uri.EscapeDataString(query)}/3",
            },
            new
            {
                title = $"The Future of {query} - MIT Technology Review",
                snippet = $"Experts predict that {query} will transform multiple industries within the next decade. Key milestones are expected in scalability, cost reduction, and real-world deployment.",
                url = $"https://example.com/future/{Uri.EscapeDataString(query)}/4",
            },
            new
            {
                title = $"Challenges and Opportunities in {query} - arxiv.org",
                snippet = $"While {query} faces significant technical challenges including error rates and scalability, recent innovations suggest these barriers may be overcome sooner than expected.",
                url = $"https://example.com/challenges/{Uri.EscapeDataString(query)}/5",
            },
        };

        return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;

namespace ResearchAgent;

/// <summary>
/// A note-taking tool that allows the agent to record and retrieve findings during research.
/// </summary>
public sealed class Notepad
{
    private readonly List<string> _notes = [];

    [Description("Adds a note to the research notepad. Use this to record important findings, key facts, or insights discovered during research.")]
    public string AddNote(
        [Description("The note content to save, such as a key finding or important fact")] string note)
    {
        _notes.Add(note);
        return $"Note #{_notes.Count} saved: \"{note}\"";
    }

    [Description("Retrieves all notes taken so far during the research session. Use this to review findings before writing a summary.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been taken yet.";
        }

        var formatted = _notes.Select((n, i) => $"{i + 1}. {n}");
        return $"Research notes ({_notes.Count} total):\n{string.Join('\n', formatted)}";
    }

    /// <summary>Gets all notes as a list (for display in the console).</summary>
    public IReadOnlyList<string> GetAllNotes() => _notes.AsReadOnly();
}

