using System.ComponentModel;

namespace ResearchAgent;

/// <summary>
/// A note-taking tool that allows the agent to record and retrieve findings during research.
/// </summary>
public sealed class Notepad
{
    private readonly List<string> _notes = [];

    [Description("Adds a note to the research notepad. Use this to record important findings, key facts, or insights discovered during research.")]
    public string AddNote(
        [Description("The note content to save, such as a key finding or important fact")] string note)
    {
        _notes.Add(note);
        return $"Note #{_notes.Count} saved: \"{note}\"";
    }

