using Microsoft.Agents.AI;
using ResearchAgent;

var configuration = new ConfigurationBuilder()
    .AddEnvironmentVariables()
    .Build();

var apiKey = configuration["OPENAI_API_KEY"]
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var modelId = configuration["OPENAI_MODEL"] ?? "gpt-4o-mini-2024-07-18";

var services = new ServiceCollection();

services.AddLogging(builder => builder
    .AddConsole()
    .SetMinimumLevel(LogLevel.Information));

services.AddChatClient(builder => builder
    .UseFunctionInvocation()
    .Use(new OpenAI.OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient()));

var provider = services.BuildServiceProvider();
var chatClient = provider.GetRequiredService<IChatClient>();
var logger = provider.GetRequiredService<ILogger<Program>>();

// Set up tools
var notepad = new Notepad();
var tools = new List<AITool>
{
    AIFunctionFactory.Create(WebSearchTool.SearchWebAsync),
    AIFunctionFactory.Create(notepad.AddNote),
    AIFunctionFactory.Create(notepad.GetNotes),
};

// Determine topic
var topic = args.Length > 0 ? string.Join(' ', args) : "the latest advances in quantum computing";

Console.WriteLine($"🔍 Researching: {topic}\n");

var systemPrompt = """
    You are a research agent. Your goal is to research a topic thoroughly by:
    1. Searching the web for relevant information (perform multiple searches with different queries)
    2. Taking notes on key findings as you go
    3. After gathering enough information, reviewing your notes and providing a comprehensive summary

    Be thorough but concise. Focus on the most important and recent information.
    Always take notes on important findings before moving to the next search.
    When you have enough information (at least 3-5 searches), provide a final summary.
    """;

// Create the agent using Microsoft Agent Framework
var agent = chatClient.AsAIAgent(new ChatClientAgentOptions
{
    Name = "ResearchAgent",
    Description = "An AI agent that researches topics by searching the web and taking notes.",
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
        Tools = tools,
    },
});

Console.WriteLine("Agent is working...\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}"),
};

// Run the agent with streaming output
await foreach (var update in agent.RunStreamingAsync(messages))
{
    if (!string.IsNullOrEmpty(update.Text))
    {
        Console.Write(update.Text);
    }
}

Console.WriteLine("\n\n--- Notes Collected ---");
foreach (var note in notepad.GetAllNotes())
{
    Console.WriteLine($"• {note}");
}

Console.WriteLine("\n✅ Research complete.");

